/**
 * The fourth review's corpus of good writing (copied from the reviewer's scripts, not changed in substance):
 * sixteen good articles written without counting anything first, and the natural edits to them that the reviewer
 * scored (its two tables). Each variant carries the reviewer's verdict: `deserved: false` means the lower score it
 * got at e1eeb7c was not deserved, so it must pass the gate with a picture and score no lower than at d4e5527.
 */
import type { ArticleBody, ArticleBrief } from '../src/seo-blog/types.js';

export interface Art { readonly name: string; readonly site: string; readonly brief: Pick<ArticleBrief, 'targetQuery' | 'searchIntent' | 'relatedQuestions'>; readonly body: ArticleBody }
const cite = (url: string, title: string) => ({ sourceId: title, url, title, retrievedAt: '2026-11-01T10:00:00.000Z', passage: title, public: true });
const img = (url: string, alt: string) => ({ kind: 'brand_asset', url, alt, provenance: '', width: 1536, height: 1024 });
const sec = (rows: [string, string][]) => rows.map(([heading, body], i) => ({ id: `s${i}`, heading, body }));

// 1 ── CHECKLIST POST (legitimately mostly short items)
export const CHECKLIST: Art = { name: '1 checklist post', site: 'https://www.brightdoorcleaning.example',
  brief: { targetQuery: 'end of tenancy cleaning checklist', searchIntent: 'learn', relatedQuestions: ['How clean does a property need to be at the end of a tenancy?', 'Can a landlord charge for cleaning?', 'How long does an end of tenancy clean take?'] },
  body: { title: 'End of tenancy cleaning checklist: room by room', seoTitle: 'End of tenancy cleaning checklist: every room, in order',
    metaDescription: 'Use our end of tenancy cleaning checklist to work through the kitchen, bathrooms and bedrooms in order, and hand the keys back without a deduction.',
    excerpt: 'A room-by-room list for the last clean before you hand back the keys.', slug: 'end-of-tenancy-cleaning-checklist',
    intro: `More deposit disputes are about cleaning than about anything else. The good news is that the standard is not a mystery: the property should be as clean as it was on the day you moved in, allowing for fair wear and tear.\n\nThis end of tenancy cleaning checklist takes you through the home room by room, in the order our own teams work. Print it, tick things off and take photos as you finish each room.`,
    sections: sec([
      ['Before you start', `Dig out the inventory and check-in report from the start of the tenancy. That report is what the agent will compare the property against, so it tells you exactly how clean each room needs to be.\n\nThen gather your kit so you are not stopping every ten minutes:\n\n- rubber gloves and old cloths\n- a degreaser for the kitchen\n- limescale remover\n- glass cleaner\n- a vacuum cleaner with a crevice tool\n- a mop and bucket\n- bin bags\n\nWork from the top of each room down, and from the back of the property towards the front door.`],
      ['Kitchen', `The kitchen takes the longest and is where most deductions come from. Allow half a day for it.\n\n- Empty every cupboard and drawer and wipe inside\n- Clean the oven, shelves and door glass\n- Degrease the hob, rings and control knobs\n- Wash the extractor hood and change the filter\n- Defrost the freezer and dry it out\n- Wipe the fridge shelves and door seals\n- Pull out the washing machine drawer and rinse it\n- Descale the kettle, sink and taps\n- Wipe worktops, tiles and splashbacks\n- Clean the bin inside and out\n- Mop the floor, including under the appliances\n\nLeave the fridge and freezer doors open if the power will be off.`],
      ['Bathrooms', `Limescale and mould are what inspectors look for here, so give the products time to work before you scrub.\n\n- Descale the taps, shower head and screen\n- Scrub the bath, basin and shower tray\n- Clean the toilet, including under the rim and behind the seat\n- Remove mould from the sealant and grout\n- Wipe the tiles from top to bottom\n- Polish the mirrors\n- Clear hair from the plugholes\n- Wash the extractor fan cover\n- Mop the floor\n\nFinish by drying the taps and the screen with a clean cloth so they do not spot.`],
      ['Bedrooms and living rooms', `These rooms are quicker, but they are also where forgotten belongings turn up.\n\n- Check every wardrobe, drawer and shelf is empty\n- Dust the tops of wardrobes and door frames\n- Wipe skirting boards, sockets and light switches\n- Remove marks from walls and doors\n- Clean inside the windows and wipe the sills\n- Vacuum the mattress and under the bed\n- Vacuum the carpets right to the edges\n- Dust the lampshades and curtain rails\n\nIf the tenancy agreement asks for the carpets to be professionally cleaned, keep the receipt.`],
      ['Hall, stairs and outside', `People walk through the hall first, and a first impression colours the rest of the inspection.\n\n- Vacuum the stairs and wipe the banister\n- Clean the front door inside and out\n- Dust the smoke alarms and test them\n- Empty and rinse the outside bins\n- Sweep the patio, path and balcony\n- Cut the grass and weed the borders, if the garden is your responsibility\n- Take everything out of the shed, garage and loft\n\nRead the meters and photograph them on your way out.`],
      ['How clean does a property need to be at the end of a tenancy?', `As clean as the check-in report says it was when you arrived. If the report describes the oven as "professionally cleaned", that is the standard you have to match. If it says "some grease to the hob", you do not have to leave it better than you found it.\n\nFair wear and tear is not a cleaning matter. A carpet that has flattened where people walk is wear. A carpet with a red wine stain is damage. The agent can ask you to put the second right, but not the first.`],
      ['Can a landlord charge for cleaning?', `Yes, but only for the cost of bringing the property back to the standard recorded at check-in, and only out of the deposit. Since the Tenant Fees Act 2019 a landlord or agent in England cannot make you pay for a professional clean as a condition of the tenancy, and cannot charge a fixed "cleaning fee" when you leave.\n\nIf they do make a deduction, they need evidence: the check-in report, the check-out report and a receipt or quote. You can challenge a deduction free of charge through your deposit protection scheme. Our guide to [getting your deposit back](https://www.brightdoorcleaning.example/guides/getting-your-deposit-back) explains how.`],
    ]),
    conclusion: `Work through the list in order, photograph each room when it is done and keep any receipts. If you would rather hand the whole job to somebody else, we clean to the inventory and come back free of charge if the agent is not satisfied.`,
    cta: { label: 'Get a fixed price for your clean', url: 'https://www.brightdoorcleaning.example/quote' },
    faqs: [
      { q: 'How long does an end of tenancy clean take?', a: 'For one person, allow a full day for a one-bedroom flat and two days for a three-bedroom house. A professional team of three usually finishes a house in four to six hours.' },
      { q: 'Do I have to use a professional cleaner?', a: 'No. In England you cannot be required to pay for one. You only have to return the property as clean as it was at the start.' },
      { q: 'What do agents check first?', a: 'The oven, the bathroom sealant, the inside of the fridge and the carpets. Those four account for most of the cleaning deductions we see.' },
    ],
    citations: [cite('https://www.gov.uk/government/publications/tenant-fees-act-2019-guidance', 'GOV.UK: Tenant Fees Act 2019 guidance')],
    image: img('https://www.brightdoorcleaning.example/images/checklist.jpg', 'A cleaner in gloves wiping a kitchen worktop with a printed checklist beside the sink'), author: null } as unknown as ArticleBody };

// 2 ── STEP-BY-STEP HOW-TO
export const HOWTO: Art = { name: '2 step-by-step how-to', site: 'https://www.marlowelectrical.example',
  brief: { targetQuery: 'how to change a fuse in a plug', searchIntent: 'learn', relatedQuestions: ['What fuse do I need for a plug?', 'How do you know if a plug fuse has blown?', 'Is it safe to change a plug fuse yourself?'] },
  body: { title: 'How to change a fuse in a plug', seoTitle: 'How to change a fuse in a plug safely, in five minutes',
    metaDescription: 'A dead kettle or lamp is often just a blown fuse. Here is how to change a fuse in a plug safely, and how to pick the right rating.',
    excerpt: 'A blown plug fuse takes five minutes and a screwdriver to put right.', slug: 'how-to-change-a-fuse-in-a-plug',
    intro: `When a lamp, kettle or radio suddenly stops working, the fault is often the small fuse inside the plug and not the appliance itself. It is one of the few electrical jobs that anyone can do safely at home.\n\nThis guide shows you how to change a fuse in a plug, how to choose the right replacement and when to stop and call an electrician instead.`,
    sections: sec([
      ['How do you know if a plug fuse has blown?', `The simplest test is to try something else in the same socket. If a phone charger works there, the socket is fine and the problem is in the appliance or its plug.\n\nNext, try the appliance in a different socket. If it is still dead, the fuse is the most likely cause. You cannot usually tell by looking, because most plug fuses are ceramic and show no mark when they fail. If you own a multimeter, a good fuse will show continuity and a blown one will not.`],
      ['What fuse do I need for a plug?', `Use the rating the manufacturer fitted. It is printed on the old fuse and often on the plug or the appliance label as well.\n\nAs a rule of thumb, appliances up to about 700 watts take a 3 amp fuse, which covers lamps, televisions, radios and chargers. Anything with a heating element or a large motor, such as a kettle, toaster, iron or vacuum cleaner, takes a 13 amp fuse. Some equipment uses a 5 amp fuse.\n\nNever fit a bigger fuse to stop it blowing. The fuse is there to protect the flex, and a 13 amp fuse on a thin lamp cable will let the cable overheat before it fails.`],
      ['What you will need', `You only need two things: a small flat-headed or cross-headed screwdriver, depending on the plug, and a new fuse of the right rating marked BS 1362. Buy fuses from a proper retailer, because counterfeit ones do turn up online.`],
      ['Changing the fuse, step by step', `Take your time and keep the screws somewhere safe.\n\n1. Switch off at the socket and pull the plug out. Never open a plug that is still plugged in.\n2. Turn the plug over. On a moulded plug, the fuse sits in a small carrier between the pins, and you can lever it out with the screwdriver.\n3. On a plug with a removable cover, undo the large screw in the middle and lift the cover off.\n4. Ease the old fuse out of its clips with the tip of the screwdriver.\n5. Check the rating printed on it, then press the new fuse firmly into the clips.\n6. While the cover is off, look at the three wires. Each one should be held tight under its screw, with no loose copper strands.\n7. Refit the cover, tighten the screw and plug the appliance back in.\n\nIf the appliance works, you are finished.`],
      ['If the new fuse blows straight away', `Stop there. A fuse that fails the moment you switch on is doing its job, and it is telling you that there is a fault in the flex or in the appliance.\n\nDo not keep replacing it, and do not move up a rating. Unplug the appliance and have it looked at, or replace it if it is cheap. If several things in the house are tripping or blowing, the problem may be in the wiring, and that needs [an electrical inspection](https://www.marlowelectrical.example/services/inspection-and-testing) and not another fuse.`],
      ['Is it safe to change a plug fuse yourself?', `Yes, as long as the plug is out of the socket before you open it. There is no stored charge inside an ordinary plug, so once it is unplugged there is nothing live to touch.\n\nThe risks come from shortcuts: wrapping a blown fuse in foil, fitting the wrong rating, or forcing a cracked cover back on. If the plug is scorched, cracked or warm in use, replace the whole plug or ask an electrician to do it.`],
    ]),
    conclusion: `A blown fuse is usually a five-minute fix with a screwdriver and a spare of the same rating. If it blows again, or you spot scorch marks or damaged flex, leave it unplugged and get it checked.`,
    cta: { label: 'Book an electrician', url: 'https://www.marlowelectrical.example/book' },
    faqs: [
      { q: 'Can I use a 13 amp fuse instead of a 3 amp fuse?', a: 'No. A 13 amp fuse will not protect a thin flex designed for a 3 amp load, so the cable could overheat. Always replace a fuse with one of the same rating.' },
      { q: 'Do all plugs have a fuse?', a: 'Every standard UK three-pin plug has one. Plugs made for other countries usually do not, which is why a UK adaptor carries its own fuse.' },
      { q: 'Why does my plug fuse keep blowing?', a: 'Usually because the appliance is faulty or the flex is damaged. Occasionally the fuse fitted is simply too small for the appliance, so check the label.' },
    ],
    citations: [cite('https://www.electricalsafetyfirst.org.uk/guidance/safety-around-the-home/plugs-and-fuses/', 'Electrical Safety First: plugs and fuses')],
    image: img('https://www.marlowelectrical.example/images/plug.jpg', 'An open three-pin plug on a table with a screwdriver and a new fuse beside it'), author: null } as unknown as ArticleBody };

// 3 ── FAQ PAGE WITH SHORT ANSWERS (the phrase is the name of the thing)
export const FAQPAGE: Art = { name: '3 FAQ page, short answers', site: 'https://www.crossgatesgarage.example',
  brief: { targetQuery: 'MOT test', searchIntent: 'learn', relatedQuestions: ['How long does an MOT take?', 'What is checked in an MOT?', 'Can I drive my car if it fails its MOT?', 'How early can I get an MOT?'] },
  body: { title: 'The MOT test: your questions answered', seoTitle: 'MOT test questions answered by the people who do them',
    metaDescription: 'How long an MOT test takes, what is checked, what happens if your car fails and how early you can book. Straight answers from our testers.',
    excerpt: 'Straight answers to the questions we are asked at the counter every day.', slug: 'mot-test-questions',
    intro: `Every car over three years old needs an MOT test once a year, and every year the same questions come up at our front desk. We have put the answers in one place.\n\nIf yours is not here, ring us. One of the testers will be happy to explain.`,
    sections: sec([
      ['What is checked in an MOT?', `The tester follows a set list laid down by the Driver and Vehicle Standards Agency. It covers the things that keep the car safe and legal on the road:\n\n- brakes, including the handbrake\n- tyres and wheels\n- lights, indicators and reflectors\n- steering and suspension\n- seat belts and seats\n- windscreen, wipers and washers\n- exhaust and emissions\n- horn, mirrors and number plates\n- the body, for sharp edges and serious rust\n\nIt is not a service. The tester does not check the engine, clutch or gearbox, and a pass does not mean the car is in good mechanical order.`],
      ['How long does an MOT take?', `About 45 minutes to an hour for most cars. If you wait with us, there is a viewing area and coffee. If the car needs work to pass, we will ring you with a price before we touch anything, and a small repair can often be done the same day.`],
      ['Can I drive my car if it fails its MOT?', `It depends on why it failed and whether last year's certificate is still in date. If the tester records a "dangerous" fault, you must not drive the car at all until it is repaired. With a "major" fault you may drive it away only if the old certificate has not yet run out and the car is roadworthy. Once the old certificate has expired, you may drive only to a booked repair or a booked test. We explain all of this on the day, so nobody leaves unsure.`],
      ['How early can I get an MOT?', `Up to one month, less a day, before the current certificate runs out, and you keep the same renewal date. So if yours expires on 15 May, the earliest you can have it tested and keep that date is 16 April. You can go earlier still, but the new certificate will then run for twelve months from the day of the test. You can [book a date online](https://www.crossgatesgarage.example/mot/book) in a couple of minutes.`],
    ]),
    conclusion: `If you are not sure when yours is due, the government's online checker will tell you from the registration number alone. Book a week or two early and you have time to sort out any surprises.`,
    cta: { label: 'Book your MOT', url: 'https://www.crossgatesgarage.example/mot/book' },
    faqs: [
      { q: 'How much does an MOT cost?', a: 'The legal maximum for a car is £54.85. We charge £45, and there is no fee for a partial retest within ten working days.' },
      { q: 'What do I need to bring?', a: 'Just the car and the keys. We look up everything else from the registration number. Bring the locking wheel nut key if you have one.' },
      { q: 'What are the most common reasons for failing?', a: 'Bulbs, tyres and wiper blades, in that order. All three are cheap to fix and easy to check on the drive the night before.' },
      { q: 'Do electric cars need an MOT?', a: 'Yes, from three years old, just like any other car. There is no emissions test, but everything else is checked in the same way.' },
      { q: 'Is there a grace period after the certificate expires?', a: 'No. The day after it runs out, the car cannot be driven on the road except to a test you have already booked.' },
      { q: 'Will you tell me about advisories?', a: 'Always. Advisories are items that passed today but will need attention soon, such as tyres close to the limit. We talk you through each one.' },
      { q: 'Can you collect my car?', a: 'Yes, within five miles of the garage and free of charge. Tell us when you book and we will agree a time.' },
    ],
    citations: [cite('https://www.gov.uk/getting-an-mot', 'GOV.UK: getting an MOT')],
    image: img('https://www.crossgatesgarage.example/images/ramp.jpg', 'A tester checking the brakes of a hatchback on a ramp during an MOT'), author: null } as unknown as ArticleBody };

// 4 ── PRICE GUIDE (prices as a list, the only form the article format allows)
export const PRICES: Art = { name: '4 price guide (price list)', site: 'https://www.harperheating.example',
  brief: { targetQuery: 'boiler service cost', searchIntent: 'buy', relatedQuestions: ['How much does a boiler service cost in the UK?', 'What is included in a boiler service?', 'How often should a boiler be serviced?'] },
  body: { title: 'Boiler service cost: our 2026 price guide', seoTitle: 'Boiler service cost in 2026: prices, and what you get',
    metaDescription: 'What a boiler service cost looks like in 2026, from a one-off visit to a monthly plan, with our own fixed prices and what each one includes.',
    excerpt: 'Typical prices for a boiler service this year, and what should be included.', slug: 'boiler-service-cost',
    intro: `If you are trying to budget for the year, the boiler service cost is one of the easier bills to pin down. Most homes will pay between £80 and £120 for a one-off visit from a Gas Safe registered engineer, and a little less each month on a plan.\n\nBelow are the typical prices across the country, our own fixed prices, and what you should expect for the money.`,
    sections: sec([
      ['How much does a boiler service cost in the UK?', `Prices vary with the type of boiler and where you live. These are the ranges we see quoted by independent engineers this year:\n\n- Gas combi boiler: £80 to £110\n- Gas system or regular boiler: £85 to £120\n- Oil boiler: £110 to £160\n- LPG boiler: £90 to £130\n- Back boiler: £100 to £140\n- Air source heat pump: £150 to £250\n\nNational firms tend to sit at the top of each range, and London and the South East add about a fifth. An oil boiler costs more because the engineer replaces the nozzle and cleans the burner at every visit.`],
      ['Our prices', `We charge a fixed price, agreed when you book. There is no call-out fee and no charge for parking.\n\n- Gas boiler service: £89\n- Gas boiler and gas fire together: £129\n- Oil boiler service: £135\n- Landlord gas safety certificate with a service: £119\n- Each extra gas appliance: £25\n\nAll prices include VAT. If the engineer finds a part that needs replacing, you get a written price before any work starts, and you are free to say no.`],
      ['What is included in a boiler service?', `A proper visit takes 45 minutes to an hour. If somebody is in and out in fifteen, they have not done the job. The engineer should take the case off, inspect the burner and heat exchanger, clean the condensate trap, check the flue and the seals, test the gas pressure and the flue gases with an analyser, and confirm that the safety devices work.\n\nYou should be left with a written report showing the readings. Keep it. Most boiler warranties are only valid if you can show the boiler was serviced every year.`],
      ['Is a monthly plan cheaper?', `Sometimes. A basic service plan costs from £8 a month and simply spreads the price of the annual visit. Cover plans, at £15 to £25 a month, include repairs as well. They can be good value for an older boiler and poor value for a new one that is still under the manufacturer's warranty.\n\nRead what is excluded before you sign. Many plans do not cover sludge, scale or parts that are no longer made. Our own [boiler cover plans](https://www.harperheating.example/boiler-cover) list every exclusion on one page.`],
      ['How often should a boiler be serviced?', `Once a year. Manufacturers require it for the warranty, and landlords must have gas appliances checked every twelve months by law. Late summer is the best time to book, because engineers are quieter and any fault is found before you need the heating.`],
    ]),
    conclusion: `Expect to pay around £90 for a gas boiler and a little more for oil. Whoever you use, check that they are on the Gas Safe Register and ask for the report in writing.`,
    cta: { label: 'Book a boiler service', url: 'https://www.harperheating.example/book' },
    faqs: [
      { q: 'Why is an oil boiler service more expensive?', a: 'It takes longer and uses parts. The engineer fits a new nozzle, cleans the burner and checks the oil line and filter at every visit.' },
      { q: 'Do I pay if the boiler fails the service?', a: 'You pay for the visit. Any repair is quoted separately and nothing is done until you have agreed the price in writing.' },
      { q: 'Is a gas safety certificate the same as a service?', a: 'No. The certificate confirms the appliance is safe to use. A service also cleans and adjusts the boiler so it runs well.' },
    ],
    citations: [cite('https://www.gassaferegister.co.uk/gas-safety/gas-safety-in-the-home/servicing-your-appliances/', 'Gas Safe Register: servicing your appliances')],
    image: img('https://www.harperheating.example/images/service.jpg', 'An engineer with the case off a wall-hung boiler, holding a flue gas analyser'), author: null } as unknown as ArticleBody };

// 5 ── GLOSSARY (definitions as list items; single-word phrase territory handled separately)
export const GLOSSARY: Art = { name: '5 glossary', site: 'https://www.ashbylaw.example',
  brief: { targetQuery: 'conveyancing terms explained', searchIntent: 'learn', relatedQuestions: ['What does exchange of contracts mean?', 'What is the difference between exchange and completion?', 'What are searches when buying a house?'] },
  body: { title: 'Conveyancing terms explained in plain English', seoTitle: 'Conveyancing terms explained in plain English: an A to Z',
    metaDescription: 'Baffled by your solicitor\'s emails? Here are the conveyancing terms explained in plain English, from completion to transfer deed.',
    excerpt: 'The words your solicitor uses, and what they mean.', slug: 'conveyancing-terms-explained',
    intro: `Buying or selling a home comes with its own vocabulary, and solicitors are not always good at translating it. This page has the common conveyancing terms explained in plain English, so you can read the next email from your lawyer without reaching for a dictionary.\n\nThe words are grouped by the stage at which you are likely to meet them.`,
    sections: sec([
      ['At the start', `These come up in the first week or two, when you instruct a solicitor and the paperwork begins.\n\n- **Client care letter**: the letter that sets out what your solicitor will do, what it will cost and who is handling your file.\n- **Memorandum of sale**: a note from the estate agent confirming the price, the buyer, the seller and both solicitors.\n- **Title**: the legal ownership of the property. "Checking the title" means making sure the seller really owns what they are selling.\n- **Title register and title plan**: the official record at HM Land Registry of who owns the property, and a map of its boundaries.\n- **Freehold**: you own the building and the land it stands on, with no time limit.\n- **Leasehold**: you own the property for a fixed number of years under a lease, and somebody else owns the land.`],
      ['What are searches when buying a house?', `Searches are questions your solicitor puts to public bodies about the property and the area around it. A mortgage lender will insist on them. The usual ones are below.\n\n- **Local authority search**: planning history, building control, road schemes and conservation areas.\n- **Drainage and water search**: whether the property is connected to the mains and the public sewer.\n- **Environmental search**: flood risk, contaminated land and ground stability.\n- **Chancel repair search**: whether the owner could be asked to pay towards repairs to a parish church. It is rare, but it still exists.\n\nResults usually come back within two to three weeks, depending on the council.`],
      ['In the middle', `This is the longest stage, and the one where most of the jargon lives.\n\n- **Enquiries**: questions your solicitor asks the seller's solicitor after reading the contract pack and the search results.\n- **Property information form**: the seller's answers about boundaries, disputes, building work and services. It is also called the TA6.\n- **Fittings and contents form**: the list of what stays and what goes, from curtains to the garden shed.\n- **Mortgage offer**: the lender's formal agreement to lend. Until you have it, you cannot commit to a date.\n- **Indemnity insurance**: a one-off policy that covers a known gap in the paperwork, such as a missing building regulations certificate.\n- **Covenant**: a promise attached to the land. A restrictive covenant might stop you running a business from the house or keeping chickens.\n- **Easement**: a right over somebody else's land, such as a right of way across a shared drive.`],
      ['What does exchange of contracts mean?', `Exchange is the point of no return. Both solicitors hold a signed copy of the contract, they agree a completion date over the telephone, and the buyer's deposit is sent to the seller's solicitor. From that moment the deal is legally binding. A buyer who pulls out after exchange loses the deposit, and a seller who pulls out can be sued.\n\nUntil exchange, either side can walk away without penalty, which is why the weeks before it feel so tense.`],
      ['What is the difference between exchange and completion?', `Exchange makes the deal binding. Completion is the day it actually happens: the money moves, the seller hands over the keys and the buyer becomes the owner. The gap between the two is often one or two weeks, though they can take place on the same day.\n\nOn the day itself you may hear two more terms.\n\n- **Completion statement**: your solicitor's final account, showing every payment in and out.\n- **Transfer deed**: the document that moves ownership from seller to buyer. It is also called the TR1.`],
      ['After you move', `Two jobs remain, and your solicitor does both.\n\n- **Stamp Duty Land Tax**: the tax on buying property in England and Northern Ireland. The return must be filed within 14 days of completion.\n- **Registration**: your solicitor applies to HM Land Registry to put the property in your name. It can take several months, but you are protected in the meantime.\n\nIf you want to see where your own purchase has got to, our [step-by-step timeline](https://www.ashbylaw.example/guides/conveyancing-timeline) shows each stage in order.`],
    ]),
    conclusion: `You do not need to learn the language to move house, but knowing a dozen words makes the emails far less alarming. If your solicitor uses a term you do not recognise, ask. A good one will always explain.`,
    cta: { label: 'Get a conveyancing quote', url: 'https://www.ashbylaw.example/quote' },
    faqs: [
      { q: 'What is a contract pack?', a: 'The bundle the seller\'s solicitor sends at the start: the draft contract, the title documents and the seller\'s completed forms. Your solicitor cannot begin until it arrives.' },
      { q: 'What does "subject to contract" mean?', a: 'That nothing is binding yet. An offer accepted subject to contract can still be withdrawn by either side until contracts are exchanged.' },
      { q: 'What is a disbursement?', a: 'A cost your solicitor pays to somebody else on your behalf, such as search fees or Land Registry fees. It is listed separately from the solicitor\'s own fee.' },
    ],
    citations: [cite('https://www.gov.uk/buy-sell-your-home', 'GOV.UK: buying or selling your home')],
    image: img('https://www.ashbylaw.example/images/keys.jpg', 'House keys resting on a signed contract beside a pen'), author: null } as unknown as ArticleBody };

// 6 ── "10 BEST" LIST
export const TENBEST: Art = { name: '6 "10 best" list', site: 'https://www.fernbankgardencentre.example',
  brief: { targetQuery: 'best plants for shade', searchIntent: 'learn', relatedQuestions: ['What plants grow in full shade?', 'What flowers bloom in shade all summer?', 'What can I plant under trees?'] },
  body: { title: 'The 10 best plants for shade', seoTitle: '10 best plants for shade that actually flower in the UK',
    metaDescription: 'A north-facing border does not have to be bare. These are the 10 best plants for shade in a British garden, chosen by our nursery team.',
    excerpt: 'Ten reliable plants for the gloomy corners of a British garden.', slug: 'best-plants-for-shade',
    intro: `Every garden has a corner the sun never quite reaches: the border under the fence, the strip beside the garage, the bed beneath the old apple tree. Most people give up on these spots, which is a shame, because some of the loveliest plants we sell prefer them.\n\nThese are the best plants for shade that we grow ourselves, all hardy across the UK and all happy without a day of direct sun.`,
    sections: sec([
      ['First, what kind of shade do you have?', `It matters more than anything else on this page. Light shade is open to the sky but gets no direct sun, as you find on the north side of a house. Dappled shade is the moving light under a birch or a rowan. Full shade gets under two hours of sun a day, and dry shade, under conifers and big hedges, is the hardest of all.\n\nMost of the plants below cope with any of the first three. We have said where one is fussy.`],
      ['Five for flowers', `Shade does not mean green and nothing else.\n\n1. **Hellebore.** Flowers from January to April, when nothing else will. Give it rich soil and cut off the old leaves in December so you can see the blooms.\n2. **Foxglove.** Tall spires in early summer, loved by bumblebees. It is a biennial, so let it seed around and you will never be without it.\n3. **Astrantia.** Pincushion flowers in pink, white or deep red from June to September. It needs soil that does not dry out.\n4. **Japanese anemone.** Starts in August and carries on until the frosts. It is slow to settle, then hard to stop.\n5. **Hardy geranium.** 'Rozanne' flowers for five months, and the wood cranesbill is happy even under trees.`],
      ['Five for leaves', `Foliage is what makes a shady border look good for the other nine months.\n\n6. **Hosta.** The classic choice for bold leaves. Grow it in a pot with copper tape round the rim if slugs are a problem.\n7. **Fern.** The male fern will put up with dry shade once it is established, which very few plants do.\n8. **Brunnera.** Silver heart-shaped leaves and blue flowers like forget-me-nots in spring. 'Jack Frost' is the one to ask for.\n9. **Heuchera.** Evergreen mounds in lime, amber and plum. It is best in light shade, as the colours fade in deep gloom.\n10. **Sweet box.** A small evergreen shrub with a scent in January that stops people on the path.`],
      ['What plants grow in full shade?', `Fewer, but not none. Ferns, hostas, sweet box and ivy all manage on very little light, and so does lily of the valley if the soil is damp. Flowers are harder. Hellebores and foxgloves will bloom in full shade, though less freely, and snowdrops are happy anywhere that is not baked dry.\n\nIf nothing has ever grown in the spot, check the soil before you blame the light. Ground at the foot of a wall is often bone dry, and a bucket of compost dug in will do more than any plant choice.`],
      ['What can I plant under trees?', `Tree roots take most of the water, so choose plants that do their growing early, before the leaves open. Snowdrops, wood anemones, bluebells and hardy cyclamen all flower and die back by late spring. For cover later in the year, add ferns, wood cranesbill and sweet woodruff.\n\nPlant small and water well for the first summer. A young plant in a nine-centimetre pot settles in under a tree far better than a big one. There is more detail in our guide to [planting under trees](https://www.fernbankgardencentre.example/advice/planting-under-trees).`],
    ]),
    conclusion: `Start with three or four of these, plant them in groups and give them a year to settle. A shady border comes into its own in its second spring, and it asks for far less watering than a sunny one.`,
    cta: { label: 'Visit the nursery', url: 'https://www.fernbankgardencentre.example/visit' },
    faqs: [
      { q: 'What flowers bloom in shade all summer?', a: 'Hardy geranium \'Rozanne\' and astrantia flower from June to September in shade, and Japanese anemones take over from August. Busy lizzies and begonias do the same job in pots.' },
      { q: 'Will lavender grow in shade?', a: 'No. Lavender needs full sun and sharp drainage. In shade it grows leggy, flowers poorly and usually rots within a couple of winters.' },
      { q: 'When should I plant a shady border?', a: 'Autumn is best, while the soil is still warm and the rain does the watering for you. Spring is the next best time.' },
    ],
    citations: [cite('https://www.rhs.org.uk/garden-design/shade-gardening', 'RHS: shade gardening')],
    image: img('https://www.fernbankgardencentre.example/images/shade-border.jpg', 'Hostas, ferns and white foxgloves growing in a shady border beside a brick wall'), author: null } as unknown as ArticleBody };

// 7 ── RECIPE-STYLE POST (ingredients and method)
export const RECIPE: Art = { name: '7 recipe-style post', site: 'https://www.millstreetbakery.example',
  brief: { targetQuery: 'sourdough starter recipe', searchIntent: 'learn', relatedQuestions: ['How long does it take to make a sourdough starter?', 'How do I know when my sourdough starter is ready?', 'What flour is best for a sourdough starter?'] },
  body: { title: 'Our sourdough starter recipe', seoTitle: 'Sourdough starter recipe: flour, water and seven days',
    metaDescription: 'The sourdough starter recipe we teach in our bread classes: two ingredients, five minutes a day, and ready to bake with in about a week.',
    excerpt: 'Flour, water and a week of patience.', slug: 'sourdough-starter-recipe',
    intro: `A starter is nothing more than flour and water left to ferment. Wild yeast from the flour and the air moves in, and after about a week you have a bubbling culture that will raise a loaf with no shop-bought yeast at all.\n\nThis is the sourdough starter recipe we hand out at our Saturday classes. It takes five minutes a day.`,
    sections: sec([
      ['What you need', `Nothing special, and you probably own most of it already.\n\n- a clean glass jar of about 500ml\n- kitchen scales\n- a spoon or small spatula\n- an elastic band\n- 500g wholemeal or rye flour\n- 500g strong white bread flour\n- water\n\nIf your tap water smells strongly of chlorine, leave a jug of it out overnight before you use it.`],
      ['What flour is best for a sourdough starter?', `Start with wholemeal or rye. The bran carries far more wild yeast than white flour, so the culture gets going faster. After the first few days you can switch to strong white flour, which is cheaper and gives a milder flavour.\n\nAvoid self-raising flour, and avoid anything bleached. Organic flour is nice to have but not essential.`],
      ['The method, day by day', `Keep the jar somewhere warm, around 21 to 25 degrees, and out of direct sun. The top of the fridge is ideal.\n\n1. Day one. Mix 50g wholemeal flour with 50g warm water in the jar. Cover it loosely and leave it for 24 hours.\n2. Day two. You may see a bubble or two. Add another 50g flour and 50g water, and stir well.\n3. Day three. Throw away half of the mixture. Feed what is left with 50g flour and 50g water.\n4. Days four and five. Do the same again each day. It should now smell sour and fruity, and rise a little after each feed.\n5. Day six. Switch to strong white flour. Discard half and feed as before.\n6. Day seven. Mark the level with the elastic band after feeding. If the starter doubles within six hours, it is ready.\n\nIn a cold kitchen the whole thing can take ten days. That is normal.`],
      ['How do I know when my sourdough starter is ready?', `Three signs, and you want all of them. It doubles in size within four to six hours of a feed. The surface is domed and covered in bubbles of different sizes. And it smells pleasantly sharp, like yoghurt or cider, with no trace of nail varnish.\n\nYou can also drop a teaspoonful into a glass of water. If it floats, there is enough gas in it to raise a loaf.`],
      ['Keeping it alive', `Once it is established, a starter is hard to kill. If you bake every day, keep it on the worktop and feed it daily. If you bake once a week, keep it in the fridge and feed it the night before you need it.\n\nA layer of grey liquid on top means it is hungry. Pour the liquid off, feed it twice, and it will recover. Pink or orange streaks mean mould, and that is the one time you should throw it away and start again. When you are ready to use it, our [beginner's sourdough loaf](https://www.millstreetbakery.example/recipes/beginners-sourdough-loaf) is the place to begin.`],
    ]),
    conclusion: `Be patient through days three and four, when it often goes quiet. Keep feeding it and it will come back stronger. In a week you will have a starter that, looked after, can outlive the jar.`,
    cta: { label: 'Book a bread class', url: 'https://www.millstreetbakery.example/classes' },
    faqs: [
      { q: 'How long does it take to make a sourdough starter?', a: 'About seven days in a warm kitchen and up to ten in a cool one. It needs five minutes of attention each day.' },
      { q: 'Why do I have to throw half away?', a: 'Without discarding, the amount doubles at every feed and the yeast runs short of food. The discard is good in pancakes and crumpets.' },
      { q: 'Can I use plain flour?', a: 'Yes, though it is slower to get going. Use wholemeal for the first three days if you can, and plain flour after that.' },
    ],
    citations: [cite('https://www.food.gov.uk/safety-hygiene/home-baking', 'Food Standards Agency: baking at home')],
    image: img('https://www.millstreetbakery.example/images/starter.jpg', 'A glass jar of bubbling starter with an elastic band marking its level'), author: null } as unknown as ArticleBody };

